<?php require 'config.php'; $page_title='Payment — HOSTNEIL'; $d=store_read(); $id=(int)($_GET['order']??0); $order=null; foreach($d['orders'] as $o)if((int)$o['id']===$id)$order=$o; if(!$order){http_response_code(404);require 'includes/header.php';echo '<section class="section wrap"><h2>Order not found</h2></section>';require 'includes/footer.php';exit;} $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$d=store_read();$tx=trim($_POST['transaction_id']??'');$method=trim($_POST['method']??'');$amount=(float)($_POST['amount']??0);if(!$tx||!in_array($method,['bKash','Nagad','Bank Transfer'],true)||$amount<=0)$err='Enter payment method, amount, and transaction/reference ID.';else{$pid=$d['next_payment_id']++;$d['payments'][]=['id'=>$pid,'order_id'=>$id,'email'=>$order['email'],'method'=>$method,'amount'=>$amount,'transaction_id'=>$tx,'status'=>'pending','created'=>date('Y-m-d H:i:s')];foreach($d['orders'] as &$oo)if((int)$oo['id']===$id)$oo['status']='payment_submitted';unset($oo);store_write($d);flash('Payment reference submitted. Service is not active until HOSTNEIL verifies it.');redirect('dashboard.php');}}
require 'includes/header.php'; ?>
<section class="section"><div class="wrap"><form class="formbox" method="post"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><span class="eyebrow">PAYMENT REFERENCE</span><h2>Order #<?= (int)$id ?></h2><p>Service: <?= h($order['service']) ?> · <?= h($order['plan']) ?></p><p>Requested amount: <b><?= money($order['price']) ?></b></p><div class="notice"><b>bKash:</b> <?= h(BKASH_NUMBER) ?><br><b>Nagad:</b> <?= h(NAGAD_NUMBER) ?><br><br>Use the official number only after confirming the final amount with HOSTNEIL. These numbers are placeholders until configured in config.php.</div><?php if($err): ?><div class="flash error"><?= h($err) ?></div><?php endif; ?><label>Payment method<select name="method"><option>bKash</option><option>Nagad</option><option>Bank Transfer</option></select></label><label>Amount sent (BDT)<input type="number" name="amount" min="1" required></label><label>Transaction ID / Reference<input name="transaction_id" required></label><button class="btn full">Submit payment reference</button><p class="small">Submitting a reference does not automatically verify payment. An administrator must check the transaction.</p></form></div></section><?php require 'includes/footer.php'; ?>